def solve(data):
    packages = data['packages']
    roots = data['roots']
    names = sorted(packages)
    best = None
    best_vector = None

    constraints = {name: [tuple(interval)] for name, interval in roots.items()}
    if any(name not in packages for name in roots):
        return {'error': 'unsatisfiable'}

    def search(selected, required):
        nonlocal best, best_vector

        for name, row in selected.items():
            if not all(low <= row['version'] <= high
                       for low, high in required.get(name, [])):
                return

        unresolved = [name for name in required if name not in selected]
        if not unresolved:
            vector = tuple(selected[name]['version'] if name in selected else -1
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best = {name: row['version'] for name, row in selected.items()}
            return

        name = min(unresolved)
        for row in eligible(packages[name], required[name]):
            next_selected = dict(selected)
            next_selected[name] = row
            next_required = {key: list(value) for key, value in required.items()}
            valid = True
            for dep in row.get('deps', []):
                dep_name = dep['name']
                if dep_name not in packages:
                    valid = False
                    break
                next_required.setdefault(dep_name, []).append((dep['min'], dep['max']))
            if valid:
                search(next_selected, next_required)

    search({}, constraints)
    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best}
